const { reconcileGraphNodeIdentities } = await import(path.join(runtime, 'gitnexus/dist/core/incremental/write-reconciliation.js'));
const adapter = await import(path.join(runtime, 'gitnexus/dist/core/lbug/lbug-adapter.js'));
