import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';

const state = path.dirname(fileURLToPath(import.meta.url));
const runtime = '/home/node/gitnexus-optimize-3805-base';
const sizes = [0, 16384, 32768, 65536, 131072, 262144, 524288, 1048576];
const protocolPath = path.join(state, 'protocol.json');
const worker = path.join(state, 'worker.mjs');
const workerSha256 = createHash('sha256').update(fs.readFileSync(worker)).digest('hex');
const protocol = {
  purpose: 'User-requested isolated memory scaling evidence; no production source edits or optimization-loop restart.',
  authorization: 'we need to prove that the memory will grow linearily',
  runtime, runtimeSha: '6aeeace8e96603fb062dcc709e834042d5a6df74', workerSha256,
  sizes, repetitions: 3, iterationsPerProcess: 3, forceGcBetweenIterations: true,
  bufferPoolBytes: 536870912, seedBufferPoolBytes: 1073741824, heapMiB: 4096, rowChunk: 1024,
  widthSweep: { count: 65536, extraBytesPerIdentityString: [128, 512], repetitions: 3 },
  soaks: [
    { count: 65536, variant: 'baseline', iterations: 40, forceGc: true },
    { count: 65536, variant: 'cooperative', iterations: 40, forceGc: true },
    { count: 1048576, variant: 'cooperative', iterations: 40, forceGc: false },
  ],
  analysis: {
    model: 'affine memory = intercept + slope * node count; fixed-length ASCII identities',
    heldOutSize: 1048576,
    fitSizes: [16384, 32768, 65536, 131072, 262144, 524288],
    assessment: 'Report all raw points, median/range, slope and R2. Check held-out peak RSS against 120% of fitted prediction plus 16 MiB. Do not interpret R2 or this finite-range check as a native allocator proof.',
    soak: 'Compare first and last ten retained samples after warmup; report slopes and max/final, including natural-GC run. Do not infer bounded leak rate from flat finite samples.',
    bytes: 'Record exact input identity UTF-8 bytes; analyze node and byte scaling separately.',
  },
  dispatch: { serial: true, maxDispatchMinutes: 90, terminateNativeWorkers: false, minimumAvailableMiB: 3072 },
};
if (fs.existsSync(protocolPath)) assert.deepEqual(JSON.parse(fs.readFileSync(protocolPath)), protocol);
else fs.writeFileSync(protocolPath, JSON.stringify(protocol, null, 2) + '\n');
assert.deepEqual(JSON.parse(fs.readFileSync(protocolPath)), protocol);
const started = Date.now();
const manifestPath = path.join(state, 'manifest.json');
const manifest = fs.existsSync(manifestPath) ? JSON.parse(fs.readFileSync(manifestPath)) : { startedAt: new Date().toISOString(), workerSha256, status: 'running', jobs: [] };
assert.equal(manifest.workerSha256, workerSha256);
function save() {
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + '\n');
  assert.equal(JSON.parse(fs.readFileSync(manifestPath)).jobs.length, manifest.jobs.length);
}
function run(name, details) {
  const output = path.join(state, `${name}.json`);
  const config = { runtime, storage: path.join(state, `fixture-${details.count}-${details.width ?? 0}`), output,
    count: details.count, width: details.width ?? 0, mode: details.mode ?? 'measure',
    variant: details.variant ?? 'baseline', iterations: details.iterations ?? 3, forceGc: details.forceGc ?? true };
  if (fs.existsSync(output)) {
    const existing = JSON.parse(fs.readFileSync(output));
    assert.deepEqual(existing.config, config);
    if (existing.completed && manifest.jobs.some(x => x.name === name && x.status === 'complete')) return;
  }
  assert(Date.now() - started < 90 * 60000, 'Dispatch cap reached; completed results preserved');
  const available = Number(fs.readFileSync('/proc/meminfo', 'utf8').match(/^MemAvailable:\s+(\d+)/m)[1]) / 1024;
  assert(available >= 3072, 'Insufficient available memory; no new native child started');
  const configPath = path.join(state, `${name}.config.json`);
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n');
  const entry = { name, ...details, output, status: 'running', startedAt: new Date().toISOString() };
  manifest.jobs.push(entry); save();
  const fd = fs.openSync(path.join(state, `${name}.log`), 'w');
  console.log(JSON.stringify({ name, status: 'started', at: entry.startedAt }));
  try {
    execFileSync(process.execPath, ['--expose-gc', '--max-old-space-size=4096', worker, configPath], { stdio: ['ignore', fd, fd] });
  } finally { fs.closeSync(fd); }
  const result = JSON.parse(fs.readFileSync(output));
  assert(result.completed);
  assert.equal(result.identityBytes, result.config.count * (47 + 3 * result.config.width));
  entry.status = 'complete'; entry.completedAt = new Date().toISOString();
  entry.peakRssBytes = result.peakRssBytes; save();
  console.log(JSON.stringify({ name, status: 'complete', peakRssMiB: result.peakRssBytes / 1048576 }));
}
try {
  for (const count of sizes) run(`seed-${count}-0`, { mode: 'seed', count });
