});
assert.equal(samples.length, 62);
const scales = [];
for (const variant of ['baseline', 'cooperative']) for (const count of protocol.sizes) {
  const rows = samples.filter(x => x.kind === 'scale' && x.variant === variant && x.count === count);
  assert.equal(rows.length, 3);
  assert.equal(new Set(rows.map(x => x.result.identityFingerprint)).size, 1);
  scales.push({ variant, count, identityBytes: rows[0].result.identityBytes,
    peakRssMiB: summarize(rows.map(x => mib(x.result.peakRssBytes))),
    peakHeapMiB: summarize(rows.map(x => mib(x.result.sampledPeakHeapBytes))),
    retainedHeapMiB: summarize(rows.map(x => mib(x.result.finalAfterGc.heapUsed))),
    retainedRssMiB: summarize(rows.map(x => mib(x.result.finalAfterGc.rss))),
