  const iterations = sample.result.iterations.map(x => ({ i: x.i + 1, rssMiB: mib(x.retained.rss), heapMiB: mib(x.retained.heapUsed), ms: x.ms }));
  const first = iterations.slice(10, 20), last = iterations.slice(-10);
