    firstWindow: { iterations: '11–20', rssMiB: median(first.map(x => x.rssMiB)), heapMiB: median(first.map(x => x.heapMiB)) },
    lastWindow: { iterations: '31–40', rssMiB: median(last.map(x => x.rssMiB)), heapMiB: median(last.map(x => x.heapMiB)) },
    rssTailFit: fit(iterations.slice(10).map(x => ({ x: x.i, y: x.rssMiB }))),
    peakRssMiB: mib(sample.result.peakRssBytes), finalAfterGcRssMiB: mib(sample.result.finalAfterGc.rss),
    finalAfterGcHeapMiB: mib(sample.result.finalAfterGc.heapUsed), iterations };
