const failedResult = JSON.parse(fs.readFileSync(path.join(state, 'soak-1048576-cooperative-natural.json')));
assert.equal(failedResult.completed, false);
assert.equal(failedResult.iterations.length, 8);
const failedSoak = { count: 1048576, variant: 'cooperative', forceGc: false, requestedPasses: 40, verifiedPasses: 8, failingPass: 9,
