const protocol = {
  purpose: 'Verify node-count and identity-byte scaling of the direct-query routing probe under natural GC, after its 40-call soak succeeds.',
  definedAt: new Date().toISOString(), sizes: [16384,65536,131072,262144,524288,1048576],
  widthCases: [{count:65536,width:128},{count:65536,width:512}], repetitions:3, iterations:5,
  forceGcBetweenReads:false, initialAndFinalGc:true, bufferPoolBytes:536870912,
  workerSha256:createHash('sha256').update(fs.readFileSync(worker)).digest('hex'),
  analysis:'Fit median peak RSS through 524K, hold out 1M; report all ranges and errors. Assess variable bytes separately. This is a distinct diagnostic variant; do not combine its samples with prepared execution.',
  maxDispatchMinutes:15, terminateNativeWorkers:false,
};
if(process.argv.includes('--freeze')){
  assert(!fs.existsSync(protocolPath));
  fs.writeFileSync(protocolPath,JSON.stringify(protocol,null,2)+'\n');process.exit(0);
}
protocol.definedAt=JSON.parse(fs.readFileSync(protocolPath)).definedAt;
assert.deepEqual(JSON.parse(fs.readFileSync(protocolPath)),protocol);
const soak=JSON.parse(fs.readFileSync(path.join(state,'cooperative-direct-1m-natural-40.json')));
assert(soak.completed && soak.iterations.length===40,'Do not dispatch a sweep before the soak passes');
const started=Date.now(), manifest={startedAt:new Date().toISOString(),status:'running',jobs:[]};
const manifestPath=path.join(state,'direct-scaling-manifest.json');
function save(){fs.writeFileSync(manifestPath,JSON.stringify(manifest,null,2)+'\n');}
try{
  for(let repetition=1;repetition<=3;repetition++){
    let cases=[...protocol.sizes.map(count=>({count,width:0})),...protocol.widthCases];
    if(repetition===2)cases.reverse();
    for(const dimensions of cases){
      assert(Date.now()-started<15*60000,'Dispatch cap reached');
      const available=Number(fs.readFileSync('/proc/meminfo','utf8').match(/^MemAvailable:\s+(\d+)/m)[1])/1024;
