      const result=JSON.parse(fs.readFileSync(output));assert(result.completed&&result.iterations.length===5);
      entry.status='complete';entry.peakRssBytes=result.peakRssBytes;entry.finishedAt=new Date().toISOString();save();
      console.log(JSON.stringify(entry));
    }
  }
  manifest.status='complete';
}catch(error){manifest.status='failed';manifest.error=String(error);throw error;}
finally{manifest.finishedAt=new Date().toISOString();save();}

